extra_css:
/* theme: warm-home (2026-10-27) */
:root,:root:not(x){--bg:#fbf6ec;--fg:#222;--muted:#4f4a42;--line:#e5d9c3;--card:#fffdf8;--soft:#f3ead8;--accent:#0b6b80;--accent2:#d98a06}
@media (prefers-color-scheme:dark){:root{--bg:#fbf6ec;--fg:#222;--muted:#4f4a42;--line:#e5d9c3;--card:#fffdf8;--soft:#f3ead8;--accent:#0b6b80;--accent2:#d98a06}}
body{font-family:"BIZ UDPGothic","Hiragino Sans",sans-serif;font-size:17.5px;line-height:2}
header{background:#fffdf8;border-bottom:4px solid #0b6b80}
.logo,.hero h1,article h1,.sec-h,article h2,.picks-h,.next-h,aside .box-h{font-family:"Zen Maru Gothic","Hiragino Maru Gothic ProN",sans-serif;font-weight:700}
.logo{color:#0b6b80}.logo span{color:#d98a06}
.tagline,.date,.crumb,.card p,.pick span{font-size:14px}
.gnav a{background:#fffdf8;border:2px solid #0b6b80;color:#0b6b80;font-size:15px;padding:7px 16px}
.gnav a:hover,.gnav a.on{background:#0b6b80;color:#fff}
.hero-img{border-radius:24px}
.hero p{font-size:16.5px;color:#3a362f}
.sec-h{border-bottom:0;background:#0b6b80;color:#fff;border-radius:14px;padding:8px 16px}.sec-h a{color:#fff}
.card{border:2px solid #e5d9c3;border-radius:20px}
.thumb{border-radius:18px 18px 0 0}
.card:hover{border-color:#d98a06}
.card h2,.card h3{font-size:17px}
.tag{background:#d98a06;color:#222;font-weight:700;font-size:13px}
article h2{background:#e6f2f3;border-left:0;border-radius:16px;padding:12px 18px;box-shadow:inset 6px 0 0 #0b6b80}
article h3{border-bottom:3px solid #f2cf8a}
.eyecatch{border-radius:20px}
.lead,.toc,.shop,aside .box,.author{border:2px solid #e5d9c3;border-radius:16px}
.lead{font-size:15.5px}.toc{font-size:15.5px;border-top:6px solid #0b6b80}
.note{border-left:6px solid #d98a06;background:#fff7e6;border-radius:12px}
.btn{font-size:15px;padding:9px 20px}
table{font-size:15.5px}th{background:#e6f2f3}
.picks{border:3px solid #0b6b80;border-radius:20px}
.next{border:3px dashed #d98a06;border-radius:20px;background:#fff7e6}.next-h{color:#0b6b80}
.avatar{background:#d98a06;color:#222}
aside .box{font-size:15px}aside .box-h{border-bottom:3px solid #0b6b80}
.mini img{border-radius:10px}.mini b{background:#0b6b80}
footer{background:#0b6b80;color:#e6f2f3;border-top:0;font-size:14px}footer a{color:#fff}

/* hero-base: 2026-10-27 トップの見せ場の共通部分 */
.hx{padding:24px 0 6px}.hx-eyebrow{font-size:13px;font-weight:700;letter-spacing:.08em;color:var(--accent);margin:0 0 8px}
.hx-h1{font-size:clamp(28px,5vw,46px);line-height:1.3;margin:0 0 14px}.hx-h1 em{font-style:normal;color:var(--accent)}
.hx-lead{color:var(--muted);font-size:15px;margin:0 0 22px;max-width:680px}
.hx-chips{display:flex;flex-wrap:wrap;gap:8px;margin:16px 0 26px}.hx-chips a{text-decoration:none;font-size:13px;padding:5px 12px}
.hx-vs{display:grid;grid-template-columns:1fr auto 1fr;gap:12px;align-items:center;margin:0 0 22px}.hx-vs p{margin:0;font-size:13px;color:var(--muted)}
.hx-k{font-size:12px;color:var(--muted)}.hx-v{font-size:clamp(20px,3.4vw,28px);font-weight:800;line-height:1.35;margin:4px 0}
.hx-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:0 0 22px}.hx-stats b{display:block;line-height:1.1;font-variant-numeric:tabular-nums}.hx-stats span{font-size:12px;color:var(--muted)}
.hx-steps{list-style:none;padding:0;margin:0 0 8px;display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.hx-steps strong{display:block;font-size:15px}.hx-steps span{font-size:12px;color:var(--muted)}
@media (max-width:560px){.hx-vs,.hx-steps{grid-template-columns:1fr}.hx-stats{gap:6px}.hx-mid{justify-self:center}.hx-vs{text-align:center}}
[data-seq]>*{opacity:0;transform:translateY(6px);transition:opacity .4s,transform .4s}[data-seq]>.on{opacity:1;transform:none}
@media (prefers-reduced-motion:reduce){[data-seq]>*{opacity:1;transform:none;transition:none}}

/* hero: memo-card (2026-10-27) */
.hx-home .hx-h1{font-family:"Zen Maru Gothic",sans-serif;font-weight:700;color:#0b6b80}.hx-home .hx-h1 em{color:#222;background:linear-gradient(transparent 65%,#f2cf8a 65%)}
.hx-home .hx-lead{font-size:16.5px;color:#3a362f}
.hx-memo{background:#fffdf8;border:3px solid #0b6b80;border-radius:24px;padding:20px 24px;position:relative}
.hx-memo::before{content:"";position:absolute;top:-14px;left:28px;width:28px;height:28px;border-radius:50%;background:#d98a06;box-shadow:0 0 0 5px #fbf6ec}
.hx-memo-h{font-family:"Zen Maru Gothic",sans-serif;font-weight:700;font-size:15px;color:#0b6b80}
.hx-memo-t{font-size:clamp(19px,2.6vw,23px);line-height:1.8;font-weight:700;color:#222;min-height:130px;margin:8px 0}
.hx-memo-f{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;font-size:14px;color:#4f4a42}
.hx-go{background:#0b6b80;color:#fff;text-decoration:none;font-weight:700;font-size:16px;padding:10px 20px;border-radius:99px}
.hx-home .hx-chips a{font-size:15px;background:#fffdf8;border:2px solid #0b6b80;color:#0b6b80;border-radius:99px;padding:7px 16px;font-weight:700}.hx-home .hx-chips a:hover{background:#0b6b80;color:#fff}
.hx-home .hx-vs{background:#f3ead8;border-radius:24px;padding:20px 18px}.hx-home .hx-vs p{font-size:15px;color:#3a362f}.hx-home .hx-k{font-size:14px;color:#4f4a42;font-weight:700}
.hx-home .hx-v{font-family:"Zen Maru Gothic",sans-serif;font-weight:700;font-size:clamp(22px,3.6vw,30px)}.hx-home .hx-side.on{background:#fffdf8;border-radius:18px;padding:12px}.hx-home .hx-side.on .hx-v{color:#0b6b80}
.hx-home .hx-mid{font-family:"Zen Maru Gothic",sans-serif;font-size:18px;color:#d98a06;font-weight:700}
.hx-home .hx-stats div{background:#fffdf8;border:2px solid #e5d9c3;border-radius:20px;padding:14px;text-align:center}
.hx-home .hx-stats b{font-family:"Zen Maru Gothic",sans-serif;font-size:clamp(38px,6vw,52px);color:#d98a06}.hx-home .hx-stats span{font-size:15px;color:#3a362f}
.hx-home .hx-steps li{background:#e6f2f3;border-radius:20px;padding:14px 16px}.hx-home .hx-steps b{font-size:30px;color:#0b6b80;line-height:1}
.hx-home .hx-steps strong{font-size:18px;margin:4px 0}.hx-home .hx-steps span{font-size:15px;color:#3a362f}

/* article-base: 2026-10-27 記事ページの共通部分 */
.ax-time{display:inline-block;font-size:12px;margin-left:8px}
.ax-prog{position:fixed;left:0;right:0;top:0;height:4px;z-index:50;pointer-events:none}.ax-prog i{display:block;height:100%;width:0}
.toc li.now>a{font-weight:700}
.ax-tick{cursor:pointer}li.ax-tick{position:relative;padding-left:30px}ul>li.ax-tick{list-style:none}ul>li.ax-tick::marker{content:""!important}
li.ax-tick::before,tr.ax-tick td:first-child::before{content:"";position:absolute;left:4px;top:.45em;width:16px;height:16px;border:2px solid currentColor;border-radius:4px;opacity:.55}
.ax-tick.done{opacity:.55;text-decoration:line-through}li.ax-tick.done::after,tr.ax-tick.done td:first-child::after{content:"✓";position:absolute;left:7px;top:.05em;font-weight:800}
tr.ax-tick td:first-child{position:relative;padding-left:32px}tr.ax-tick td:first-child::before{left:8px;top:.6em}tr.ax-tick.done td:first-child::after{left:11px;top:.2em}
.ax-copy{display:block;margin:10px 0 0 auto;font:inherit;font-size:13px;font-weight:700;cursor:pointer}
@media print{.ax-prog,.ax-size,.ax-copy{display:none}}

/* article: big-text (2026-10-27) */
.ax-prog{height:6px;background:#e5d9c3}.ax-prog i{background:#0b6b80;border-radius:0 99px 99px 0}
.ax-time{font-size:14px;color:#0b6b80;font-weight:700}
.ax-size{display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin:6px 0 12px;font-size:15px;color:#4f4a42}
.ax-size button{font:inherit;font-weight:700;font-size:15px;padding:6px 16px;border-radius:99px;border:2px solid #0b6b80;background:#fffdf8;color:#0b6b80;cursor:pointer}
.ax-size button.on{background:#0b6b80;color:#fff}
html[data-size="l"] article{font-size:20px}html[data-size="xl"] article{font-size:23px;line-height:2.1}
html[data-size="l"] article table,html[data-size="xl"] article table{font-size:17px}
.lead strong::before{content:"🏠 "}
.toc ol li{padding:3px 0}.toc li.now{background:#e6f2f3;border-radius:8px}
article{counter-reset:wf}article h2{counter-increment:wf}article h2::before{content:"その" counter(wf) "　";color:#d98a06}
article h2.ax-sum::before{content:"さいごに　"}
article ul li::marker{content:"◎ ";color:#0b6b80}

/* category-base: 2026-10-27 カテゴリページの共通部分 */
.cx-page .cards{counter-reset:none}
.cx-page .card{position:relative;animation:cxin .5s both;animation-delay:calc(var(--i,0)*60ms)}
@keyframes cxin{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion:reduce){.cx-page .card{animation:none}}
.cx-head{position:relative;margin:4px 0 6px}.cx-head h1{margin:0}
.cx-intro{margin:8px 0 0}
.cx-meter{display:flex;align-items:center;gap:10px;margin:12px 0 0;font-size:13px}.cx-meter span{white-space:nowrap}.cx-meter b{font-size:1.25em}
.cx-meter i{position:relative;flex:1;height:8px;border-radius:99px;overflow:hidden;max-width:240px}
.cx-meter i::after{content:"";position:absolute;left:0;top:0;bottom:0;background:var(--cxm,#888);width:var(--w,0);transition:width .9s ease}
.cx-sort{display:inline-flex;gap:4px;margin:12px 0 0}.cx-sort button{font:inherit;font-size:13px;padding:4px 12px;cursor:pointer}
.cx-badge{position:absolute;top:10px;right:10px;font-size:12px;font-weight:700;padding:2px 10px;z-index:2}
.cx-others{margin:18px 0 8px}.cx-others strong{display:block;font-size:13px;margin-bottom:8px}.cx-others div{display:flex;flex-wrap:wrap;gap:8px}
.cx-others a{text-decoration:none;font-size:14px;padding:5px 12px}.cx-others small{margin-left:6px;opacity:.7}

/* category: big-text (2026-10-27) */
.cx-home{background:#fffdf8;border:2px solid #e5d9c3;border-left:10px solid #0b6b80;border-radius:14px;padding:18px 20px}
.cx-eye{font-size:15px;font-weight:700;color:#d98a06}
.cx-home h1{font-size:clamp(28px,4.2vw,36px);color:#2b2620}.cx-home h1 small{font-size:.55em;color:#4f4a42;margin-left:4px}
.cx-home .cx-intro{font-size:18px;line-height:1.9}
.cx-page{--cxm:#0b6b80}.cx-meter{font-size:16px}.cx-meter i{background:#e5d9c3;height:12px}.cx-meter b{color:#0b6b80}
.cx-sort button{font-size:16px;font-weight:700;padding:8px 18px;background:#fffdf8;color:#0b6b80;border:2px solid #0b6b80;border-radius:99px}.cx-sort button.on{background:#0b6b80;color:#fff}
.cx-head .ax-size{display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin:12px 0 0;font-size:15px;color:#4f4a42}
.cx-head .ax-size button{font:inherit;font-weight:700;font-size:15px;padding:6px 16px;border-radius:99px;border:2px solid #0b6b80;background:#fffdf8;color:#0b6b80;cursor:pointer}.cx-head .ax-size button.on{background:#0b6b80;color:#fff}
html[data-size="l"] .cx-page{font-size:19px}html[data-size="l"] .cx-page .card h2{font-size:19px}html[data-size="l"] .cx-page .card p{font-size:16px}
html[data-size="xl"] .cx-page .card h2{font-size:22px}html[data-size="xl"] .cx-page .card p{font-size:18px}html[data-size="xl"] .cx-home .cx-intro{font-size:22px}
.cx-page .cards{grid-template-columns:repeat(auto-fill,minmax(280px,1fr))}
.cx-page .card::before{content:"その" attr(data-no);position:absolute;top:10px;left:10px;z-index:2;background:#d98a06;color:#fff;font-weight:700;font-size:14px;border-radius:99px;padding:1px 12px}
.cx-badge{background:#0b6b80;color:#fff;border-radius:99px;font-size:14px}
.cx-others a{background:#fffdf8;border:2px solid #0b6b80;border-radius:12px;color:#0b6b80;font-weight:700;font-size:16px;padding:8px 16px}.cx-others strong{font-size:16px;color:#2b2620}
